<?php $pageTitle='Reports';require __DIR__.'/config/database.php';require __DIR__.'/includes/header.php';$issued=$pdo->query("SELECT l.*,b.title,m.member_code,m.name FROM loans l JOIN books b ON b.id=l.book_id JOIN members m ON m.id=l.member_id WHERE l.status='issued' ORDER BY l.due_date")->fetchAll();$overdue=$pdo->query("SELECT l.*,b.title,m.member_code,m.name FROM loans l JOIN books b ON b.id=l.book_id JOIN members m ON m.id=l.member_id WHERE l.status='issued' AND l.due_date<CURDATE() ORDER BY l.due_date")->fetchAll();?><h2>Reports</h2><h5 class="mt-4">Currently Issued</h5><div class="table-responsive"><table class="table table-striped"><tr><th>Member</th><th>Book</th><th>Issue Date</th><th>Due Date</th></tr><?php foreach($issued as $x):?><tr><td><?=h($x['member_code'].' - '.$x['name'])?></td><td><?=h($x['title'])?></td><td><?=h($x['issue_date'])?></td><td><?=h($x['due_date'])?></td></tr><?php endforeach;?></table></div><h5 class="mt-4">Overdue</h5><div class="table-responsive"><table class="table table-danger table-striped"><tr><th>Member</th><th>Book</th><th>Due Date</th><th>Days</th></tr><?php foreach($overdue as $x):?><tr><td><?=h($x['member_code'].' - '.$x['name'])?></td><td><?=h($x['title'])?></td><td><?=h($x['due_date'])?></td><td><?=max(0,(int)((strtotime(date('Y-m-d'))-strtotime($x['due_date']))/86400))?></td></tr><?php endforeach;?></table></div><?php require __DIR__.'/includes/footer.php';